#!/usr/bin/env python3
"""Links corporate site deploy bundle v1.12.0.

Cloudflare Pages build command:
    python3 build_site.py
Build output directory:
    dist
"""
from __future__ import annotations
import base64, hashlib, io, shutil, zipfile
from pathlib import Path

VERSION = "1.12.0"
EXPECTED_SHA256 = "61adca65339f5cc157e53ebb1e296c5c10297baedd465c55d0b2bba467fd639a"
BUNDLE_B64 = r""""""

def main():
    raw=base64.b64decode(BUNDLE_B64.encode("ascii"))
    actual=hashlib.sha256(raw).hexdigest()
    if actual!=EXPECTED_SHA256:
        raise RuntimeError("Embedded site bundle is corrupted")
    out=Path("dist")
    if out.exists(): shutil.rmtree(out)
    out.mkdir(parents=True,exist_ok=True)
    with zipfile.ZipFile(io.BytesIO(raw),"r") as archive: archive.extractall(out)
    print(f"Links site v{VERSION} generated to {out} ({len(raw)} archive bytes).")

if __name__=="__main__": main()
